// The account Live Activity (lock screen and Dynamic Island), a WidgetKit extension generated by
// @bacons/apple-targets at prebuild. It shares the app group with the app for the titles it
// shows (ActivityMetadataCache); the relay's pushes carry only ids, states and times.
/** @type {import('@bacons/apple-targets/app.plugin').ConfigFunction} */
module.exports = config => ({
  type: 'widget',
  name: 'PockymoeLiveActivity',
  displayName: 'Pockymoe',
  bundleIdentifier: '.liveactivity',
  deploymentTarget: '17.0',
  frameworks: ['SwiftUI', 'WidgetKit', 'ActivityKit'],
  entitlements: {
    'com.apple.security.application-groups': config.ios.entitlements['com.apple.security.application-groups'],
  },
});
